Lemma rs_acc_now : forall W m mx D, accessible m D 16 -> munch W m mx -> wins_hi W -> accessible mx D 16.
Proof. intros W m mx D AD MU WH. eapply accessible_transport_hi; eauto. Qed.

Lemma wins_hi_stack : forall l h, aceil <= l -> wins_hi [(l, h)].
Proof. intros l h Hl. pose proof aceil_facts as (AF & _). constructor; [right; cbn; unfold AHI_LO; lia| constructor]. Qed.
Lemma wins_hi_stack_obj : forall l h D n, aceil <= l -> aapp D n -> wins_hi [(D, D + n); (l, h)].
Proof.
  intros l h D n Hl AP. pose proof aceil_facts as (AF & _).
  constructor; [| constructor; [right; cbn; unfold AHI_LO; lia| constructor]].
  destruct AP as [[P1 P2]|[P1 P2]]; cbn; [left; lia| right; lia].
Qed.
