Definition ASvOwn (LB : list block) (m : mem) (ptr len : Z) : Prop :=
  (len = 0 /\ ptr = 0)
  \/ (1 <= len /\ exists p bs, In (p, ptr, len) LB /\ rw_cells bsegs m ptr [CB (Z.to_nat len) bs] /\ addressable m ptr len).
Definition svowned (ptr len : Z) (b : block) : Prop := 1 <= len /\ blk_addr b = ptr /\ blk_size b = len.

Section W.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis ATR : incl TRLIST (as_TR H).      (* [comment removed for export] *)

  Definition rsfree_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (LF : list fframe) (D ptr len lo B shi : Z) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : as_St H) (LB' : list block),
      as_VIS H s' (cfg_ms c) = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                  F (ret_pc ra) fc None m' (seg_rom bsegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv bsegs m' /\ stk bsegs m' lo (bv_unsigned sp)
      /\ rw_cells bsegs m' (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m' B
      /\ as_RHEAP H s' LB' m'
      /\ (forall b, In b LB' <-> (In b LB /\ ~ svowned ptr len b))
      /\ lb_bytes LB' <= lb_bytes LB /\ (length LB' <= length LB)%nat
      /\ rw_cells bsegs m' D [C8 (wz 0); C8 (wz 0)]
      /\ xpres H LB' (bv_unsigned sp) [(D, D + 16)]%Z m m'
      (* [comment removed for export] *)
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi /\ accessible m' D 16
      /\ as_AL H s' >= as_AL H s - as_Cf H len.

  Definition rsfree_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (mo : Model)
           (s : as_St H) (LB : list block) (LF : list fframe) (D ptr len lo B shi : Z) (errv : word),
      as_VIS H s msF = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F (wz P_A_FIELDS_REALLOC_STRING) fc None m (seg_rom bsegs) ->
      a1 = wz D -> a2 = wz 0 -> a3 = wz 0 ->
      rw_cells bsegs m D [C8 (wz ptr); C8 (wz len)] -> ASvOwn LB m ptr len -> 0 <= len < 2^64 ->
      as_RHEAP H s LB m -> as_AKREL H s (mkCfg msF mo) ->
      as_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk bsegs m lo (bv_unsigned sp) -> aceil <= lo -> lo <= bv_unsigned sp - RSFREE_STACK ->
      rw_cells bsegs m (errno_addr tp) [C4 errv] -> mem_inv bsegs m -> tp = wz ATP ->
      bv_unsigned sp mod 16 = 0 ->
      (* [comment removed for export] *)
      aobj LB LF D 16 -> D mod 8 = 0 -> accessible m D 16 -> (1 <= len -> D + 16 <= ptr \/ ptr + len <= D) ->
      as_RFS H LF m -> ACONST m -> stack0 m lo shi ->
      as_Cf H len <= as_AL H s ->
      as_SR H (rsfree_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF D ptr len lo B shi errv m mo)
        (mkCfg msF mo).
